using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00021 : ControllerTestBase
    {
        private Regex parameterRegex = new Regex("\\{.*?\\}");
        
        [TestMethod]
        public void Route_Does_Not_Contains_Upper_Letters()
        {
            var missingVersionPlaceholder = (from controller in Controllers
                                             from attribute in controller.Attributes
                                             where attribute.Name.Contains("Route") &&
                                                   attribute.Arguments.Any(a =>
                                                   {
                                                       var replacedParameters = parameterRegex.Replace(a, string.Empty);
                                                       return replacedParameters.Any(c => char.IsLetter(c) && char.IsUpper(c));
                                                   })
                                             select new
                                             {
                                                 Controller = controller.FullQualifiedName, 
                                                 Attribute = attribute.SyntaxTree
                                             }).ToImmutableList();


            Assert.IsTrue(missingVersionPlaceholder.IsEmpty(),
                $"Route contains invalid upper letters: {Environment.NewLine}{ConsoleTable.From(missingVersionPlaceholder)}");
            
            Assert.IsTrue(missingVersionPlaceholder.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00021

Route contains invalid upper letters. Please use only lower letters and kebap case: {Environment.NewLine}{ConsoleTable.From(missingVersionPlaceholder)}");
        }
    }
}
